entries[174548] = { ["name"] = "Höllenbestie beschwören", ["text"] = "30 Meter Reichweite\nSofort\nBeschwört eine Höllenbestie aus dem Wirbelnden Nether, die beim Einschlag 0 Feuerschaden verursacht und alle gegnerischen Ziele im Effektbereich für 2 Sek. betäubt. Die Höllenbestie steht 30 Sek. lang unter Eurem Befehl." }
