entries[174550] = { ["name"] = "Fähigkeit von Aeda: Höllenbestie beschwören", ["text"] = "Sofort\nAeda Morgenglanz erlernt die Fähigkeit 'Höllenbestie beschwören'.\n\nHöllenbestie beschwören\nBeschwört eine Höllenbestie aus dem Wirbelnden Nether, die beim Einschlag 0 Feuerschaden verursacht und alle gegnerischen Ziele im Effektbereich für 2 Sek. betäubt. Die Höllenbestie steht 30 Sek. lang unter Eurem Befehl." }
entries[174551] = { ["name"] = "Fischrogen", ["text"] = "5 Meter Reichweite\nSofort\nStellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang eine Erhöhung eines Werts um 6 . Kann für manche effektiver sein als für andere." }
entries[174552] = { ["name"] = "Sindragosas Hauch", ["text"] = "100 Meter Reichweite\nSofort\nFügt Gegnern in einem kegelförmigen Bereich von 12 Metern vor Euch im Verlauf von 6 Sek. alle 1 Sek. Schattenfrostschaden zu." }
entries[174553] = { ["name"] = "Fähigkeit von Delvar: Sindragosas Hauch", ["text"] = "Sofort\nDelvar Eisenfaust erlernt die Fähigkeit 'Sindragosas Hauch'.\n\nSindragosas Hauch\nFügt Gegnern in einem kegelförmigen Bereich von 12 Metern vor Euch im Verlauf von 6 Sek. alle 1 Sek. Schattenfrostschaden zu." }
