entries[174556] = { ["name"] = "Meteor", ["text"] = "100 Meter Reichweite\nSofort\nRuft einen Meteor herab, der nach 3 Sek. am Zielort landet und Feuerschaden verursacht. Der Meteor verbrennt außerdem den Boden, wodurch Gegner in dem Bereich 8 Sek. lang alle 5.2 Sek. zusätzlichen Feuerschaden erleiden." }
entries[174557] = { ["name"] = "Fähigkeit von Vivianne: Meteor", ["text"] = "Sofort\nVivianne erlernt die Fähigkeit 'Meteor'.\n\nMeteor\nRuft einen Meteor herab, der nach 3 Sek. am Zielort landet und Feuerschaden verursacht. Der Meteor verbrennt außerdem den Boden, wodurch Gegner in dem Bereich 8 Sek. lang alle 5.2 Sek. zusätzlichen Feuerschaden erleiden." }
entries[174558] = { ["name"] = "Arkaner Strom", ["text"] = "200 Meter Reichweite\nWirken in 1.5 sek.\nKanalisiert einen Strom arkaner Energie, der allen Gegnern innerhalb von 6 Metern um den Zielort 576 Arkanschaden zufügt." }
entries[174559] = { ["name"] = "Letzte Riten", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nVersieht das Ziel mit dem Mal des Todes, betäubt es und erhöht 9 Sek. lang seinen erlittenen Schaden um 20%.\n\nWenn 'Letzte Riten' endet oder das Ziel stirbt, fügt die anschließende Explosion Gegnern in einem Umkreis von 30 Metern 100 Schattenschaden zu." }
entries[174560] = { ["name"] = "Fähigkeit von Ishaal: Letzte Riten", ["text"] = "Sofort\nKrallenpriester Ishaal erlernt die Fähigkeit 'Letzte Riten'.\n\nLetzte Riten\nVersieht das Ziel mit dem Mal des Todes, betäubt es und erhöht 9 Sek. lang seinen erlittenen Schaden um 20%.\n\nWenn 'Letzte Riten' endet oder das Ziel stirbt, fügt die anschließende Explosion Gegnern in einem Umkreis von 30 Metern 100 Schattenschaden zu." }
